void simdunpack_u16_w256_corrected_quarter(const __m256i *in, uint16_t *out, const uint32_t bit, const uint16_t *a_block, __m256i* sum) {
  switch (bit) {
  case 0:
    /* b==0: every OutReg = its quarter anchor; aggregate them. */
    {
      size_t _k;
      for (_k = 0; _k < 16; ++_k)
        aggregate_sums_u16(_mm256_set_m128i(
            _mm_blend_epi16(_mm_set1_epi16((short)a_block[4*_k+2]),
                _mm_set1_epi16((short)a_block[4*_k+3]), 0xF0),
            _mm_blend_epi16(_mm_set1_epi16((short)a_block[4*_k]),
                _mm_set1_epi16((short)a_block[4*_k+1]), 0xF0)), sum);
    }
    (void)in; (void)out;  /* sum-only: no zero-fill of out */
    break;

  case 1:
    __SIMD_fastunpack1_16_cquarter_w256(in, out, sum, a_block);
    break;

  case 2:
    __SIMD_fastunpack2_16_cquarter_w256(in, out, sum, a_block);
    break;

  case 3:
    __SIMD_fastunpack3_16_cquarter_w256(in, out, sum, a_block);
    break;

  case 4:
    __SIMD_fastunpack4_16_cquarter_w256(in, out, sum, a_block);
    break;

  case 5:
    __SIMD_fastunpack5_16_cquarter_w256(in, out, sum, a_block);
    break;

  case 6:
    __SIMD_fastunpack6_16_cquarter_w256(in, out, sum, a_block);
    break;

  case 7:
    __SIMD_fastunpack7_16_cquarter_w256(in, out, sum, a_block);
    break;

  case 8:
    __SIMD_fastunpack8_16_cquarter_w256(in, out, sum, a_block);
    break;

  case 9:
    __SIMD_fastunpack9_16_cquarter_w256(in, out, sum, a_block);
    break;

  case 10:
    __SIMD_fastunpack10_16_cquarter_w256(in, out, sum, a_block);
    break;

  case 11:
    __SIMD_fastunpack11_16_cquarter_w256(in, out, sum, a_block);
    break;

  case 12:
    __SIMD_fastunpack12_16_cquarter_w256(in, out, sum, a_block);
    break;

  case 13:
    __SIMD_fastunpack13_16_cquarter_w256(in, out, sum, a_block);
    break;

  case 14:
    __SIMD_fastunpack14_16_cquarter_w256(in, out, sum, a_block);
    break;

  case 15:
    __SIMD_fastunpack15_16_cquarter_w256(in, out, sum, a_block);
    break;

  case 16:
    __SIMD_fastunpack16_16_cquarter_w256(in, out, sum, a_block);
    break;

  default:
    break;
  }
}
