    break;

  case 8:
    __SIMD_fastunpack8_16_cscalar3_madd_w256(in, out, sum, a_block);
    break;

  case 9:
    __SIMD_fastunpack9_16_cscalar3_madd_w256(in, out, sum, a_block);
