    break;

  case 7:
    __SIMD_fastunpack7_16_corrected_uniform_noagg_w256(in, out, sum, anchor);
    break;

  case 8:
    __SIMD_fastunpack8_16_corrected_uniform_noagg_w256(in, out, sum, anchor);
