  case 1:
    __SIMD_fastunpack1_16_chalf_shuf_noagg_w256(in, out, sum, a_block);
    break;

  case 2:
    __SIMD_fastunpack2_16_chalf_shuf_noagg_w256(in, out, sum, a_block);
    break;

  case 3:
    __SIMD_fastunpack3_16_chalf_shuf_noagg_w256(in, out, sum, a_block);
