    break;

  case 6:
    __SIMD_fastunpack6_16_chalf_shuf_noagg_w256(in, out, sum, a_block);
    break;

  case 7:
    __SIMD_fastunpack7_16_chalf_shuf_noagg_w256(in, out, sum, a_block);
    break;

  case 8:
    __SIMD_fastunpack8_16_chalf_shuf_noagg_w256(in, out, sum, a_block);
    break;

  case 9:
    __SIMD_fastunpack9_16_chalf_shuf_noagg_w256(in, out, sum, a_block);
    break;

  case 10:
    __SIMD_fastunpack10_16_chalf_shuf_noagg_w256(in, out, sum, a_block);
    break;

  case 11:
    __SIMD_fastunpack11_16_chalf_shuf_noagg_w256(in, out, sum, a_block);
    break;

  case 12:
    __SIMD_fastunpack12_16_chalf_shuf_noagg_w256(in, out, sum, a_block);
    break;

  case 13:
    __SIMD_fastunpack13_16_chalf_shuf_noagg_w256(in, out, sum, a_block);
    break;

  case 14:
    __SIMD_fastunpack14_16_chalf_shuf_noagg_w256(in, out, sum, a_block);
